	('2025-09-28 01:00:00.000', '2025-09-28 01:00:00.000', NULL, @agent_id, '表头行及列名推断机器人', '[1]', '0.5', 'prompt',
	'{{input1}}\nHelp me confirm the header rows of the table and translate them into English.\nThe column names of the answers should be in English, separated, in accordance with the database field naming rules, and in lowercase!\nMake sure that the number of converted column names returned is strictly consistent with the original number of column names you have determined, and the quantity is always the same as the original number of column names. If the actual meaning cannot be judged, it can be directly translated into English.\nIf the header column name is "id", it should be changed to "new_id" uniformly and not retained as "id".\nAt the same time, please return the number of rows of the column name you judged in json format, for example:\n{\n  "columnNames": Converted array of English column names,\n  "columnRealNames": Original array of column names,\n  "headerRow": The number of header rows\n}\nIf the original column name is empty, the converted column name cannot be empty. The column name should be inferred based on the data in the same column.\nDon\'t say anything else. Just return the conclusion!',
	'',
    '[{"input":"input1","name":"数据","description":"用户输入表头行附近的十行数据","is_title":true,"input_type":"text","input_array":[],"is_required":false}]',
    '{"prompt_template":"","doc_forest_ids":null}');
