-- 插入 chat_agent_version （忽略唯一键冲突）
INSERT INTO `chat_agent_version` (`created_at`, `updated_at`, `deleted_at`, `agent_id`, `description`, `chat_model_ids`, `temperature`, `agent_type`, `prompt_template`, `greeting_message`,`params`, `forest_option`)
VALUES
	('2025-09-28 01:00:00.000', '2025-09-28 01:00:00.000', NULL, @agent_id, '根据建表语句和示例数据，将用户的问题转为 sql', '[1]', '0.7', 'prompt',
	'The following is the structure of my table and the sample data of each table: \n{{input1}}\n\n The following are the questions I raised: \n{{input2}}\n\n Please generate SQL query statements strictly in accordance with the following rules: \n1. Database environment: MySQL 8.0+\n2. Table association rules: \n - Automatically determine the association fields between tables based on DDL and sample data \n - Default to using INNER JOIN when multiple tables are associated to ensure data validity \n3. Field handling rules: \n - Strictly prohibit the use of any columns with the yg_excel prefix \n - Only judge yg_excel_abnormal when the data itself is abnormal; for other questions, judge the anomalies based on the actual data \n - The date field must use the standard format: \n * Query condition: WHERE DATE_FORMAT(date_field, \'%Y-%m-%d\') = \'2025-01-01\' \n - text field: COALESCE(field,\'\'\'\') AS field_alias\n - numeric field: COALESCE(field,0) AS field_alias\n4. Grammar norms: \n - Use English single quotes (" ") instead of Chinese quotes (" ")\n - LIKE conditions must use wildcard format: LIKE "%keyword%" \n - must include a complete set of parentheses for WHERE conditions \n5. Result control: \n - Add LIMIT 10 BY default (unless the question specifies another quantity) \n - ORDER BY must be included when sorting is required \n - Aggregate queries must include GROUP BY\n\n Output requirements: \n only output SQL statements that can be directly executed and conform to MySQL 8 syntax: \n- Completely exclude excel_ series fields \n- Use standard date processing functions \n- Include necessary WHERE conditions \n- Default LIMIT 10\n- No comments or explanations \n Key improvement points: \n\n Explicitly prohibit all excel_ prefix fields \n Standardize the standard format for processing date fields \n Enforce the use of English single quotes (to resolve syntax errors) \n Clearly define the correct way to write the LIKE condition.',
	'',
    '[{"input":"input1","name":"ddl+数据","description":"","is_title":false,"input_type":"text","input_array":[],"is_required":true},{"input":"input2","name":"问题","description":"","is_title":false,"input_type":"text","input_array":[],"is_required":true}]',
    '{"prompt_template":"","doc_forest_ids":null}');
SELECT id INTO @agent_version_id FROM chat_agent_version WHERE agent_id = @agent_id ORDER BY id DESC LIMIT 1;
