INSERT INTO `chat_agent_version` (`created_at`, `updated_at`, `deleted_at`, `agent_id`, `description`, `chat_model_ids`, `temperature`, `agent_type`, `prompt_template`, `greeting_message`,`params`, `forest_option`)
VALUES
	('2025-09-28 01:00:00.000', '2025-09-28 01:00:00.000', NULL, @agent_id, '基于数据和 sql 生成对应的 echarts 配置', '[1]', '0.5', 'prompt',
	'Query data: {{input1}}\nMy question: {{input2}}\nGenerate a suitable Echarts chart configuration based on the above data.\nExample 1 Monthly Sales Bar Chart Analysis: {\n    "title": {\n        "text": "Monthly Sales Performance Analysis",\n        "subtext": "Monthly Sales Comparison",\n        "left": "center"\n    },\n    "tooltip": {\n        "trigger": "axis",\n        "axisPointer": {\n            "type": "shadow"\n        }\n    },\n    "legend": {\n        "data": [\n            "Sales Volume"\n        ],\n        "left": "center",\n        "top": "8%"\n    },\n    "grid": {\n        "left": "3%",\n        "right": "4%",\n        "bottom": "15%",\n        "containLabel": true\n    },\n    "xAxis": {\n        "type": "category",\n        "data": [\n            "January",\n            "February",\n            "March",\n            "April",\n            "May",\n            "June"\n        ]\n    },\n    "yAxis": {\n        "type": "value",\n        "name": "Sales"\n    },\n    "series": [\n        {\n            "name": "Sales",\n            "type": "bar",\n            "data": [\n                120,\n                200,\n                150,\n                80,\n                70,\n                110\n            ],\n            "itemStyle": {\n                "color": "#3b82f6"\n            }\n        }\n    ]\n}\n\nExample 2 User Growth Trend Line Chart: {\n    "title": {\n        "text": "User Growth Trend Analysis",\n        "subtext": "User Growth in the Last 6 Months",\n        "left": "center"\n    },\n    "tooltip": {\n        "trigger": "axis"\n    },\n    "legend": {\n        "data": [\n            "New Users"\n        ],\n        "left": "center",\n        "top": "8%"\n    },\n    "grid": {\n        "left": "3%",\n        "right": "4%",\n        "bottom": "15%",\n        "containLabel": true\n    },\n    "xAxis": {\n        "type": "category",\n        "data": [\n            "January",\n            "February",\n            "March",\n            "April",\n            "May",\n            "June"\n        ]\n    },\n    "yAxis": {\n        "type": "value",\n        "name": "Number of users"\n    },\n    "series": [\n        {\n            "name": "New users",\n            "type": "line",\n            "data": [\n                850,\n                932,\n                901,\n                1234,\n                1290,\n                1430\n            ],\n            "smooth": true,\n            "itemStyle": {\n                "color": "#10b981"\n            },\n            "lineStyle": {\n                "width": 3\n            }\n        }\n    ]\n}\n\nExample 3 User Source Distribution Pie Chart: {\n    "title": {\n        "text": "User Acquisition Channel Analysis",\n        "subtext": "User Percentage by Channel",\n        "left": "center"\n    },\n    "backgroundColor": "transparent",\n    "tooltip": {\n        "trigger": "item",\n        "formatter": "{a} <br/>{b}: {c} ({d}%)"\n    },\n    "legend": {\n        "orient": "vertical",\n        "left": "left"\n    },\n    "series": [\n        {\n            "name": "User Source",\n            "type": "pie",\n            "radius": "50%",\n            "data": [\n                {\n                    "value": 335,\n                    "name": "Search Engine"\n                },\n                {\n                    "value": 310,\n                    "name": "Direct Access"\n                },\n                {\n                    "value": 234,\n                    "name": "Email Marketing"\n                },\n                {\n                    "value": 135,\n                    "name": "Affiliate Advertising"\n                },\n                {\n                    "value": 148,\n                    "name": "Video Ad"\n                }\n            ],\n            "emphasis": {\n                "itemStyle": {\n                    "shadowBlur": 10,\n                    "shadowOffsetX": 0,\n                    "shadowColor": "rgba(0, 0, 0, 0.5)"\n                }\n            }\n        }\n    ]\n}\n\nExample 4 Product Rating Radar Analysis: {\n    "title": {\n        "text": "Product Comprehensive Rating Analysis",\n        "subtext": "Six Dimensions Evaluation Comparison",\n        "left": "center"\n    },\n    "tooltip": {\n        "trigger": "item"\n    },\n    "legend": {\n        "data": [\n            "Product A",\n            "Product B",\n            "Industry Average"\n        ],\n        "left": "center",\n        "bottom": "5%"\n    },\n    "radar": {\n        "indicator": [\n            {\n                "name": "User Experience",\n                "max": 100\n            },\n            {\n                "name": "Functional Completeness",\n                "max": 100\n            },\n            {\n                "name": "Performance",\n                "max": 100\n            },\n            {\n                "name": "Security",\n                "max": 100\n            },\n            {\n                "name": "Ease of Use",\n                "max": 100\n            },\n            {\n                "name": "Value for Money",\n                "max": 100\n            }\n        ],\n        "center": [\n            "50%",\n            "50%"\n        ],\n        "radius": "60%"\n    },\n    "series": [\n        {\n            "name": "Product Rating",\n            "type": "radar",\n            "data": [\n                {\n                    "value": [\n                        85,\n                        90,\n                        78,\n                        92,\n                        88,\n                        85\n                    ],\n                    "name": "Product A",\n                    "itemStyle": {\n                        "color": "#3b82f6"\n                    }\n                },\n                {\n                    "value": [\n                        75,\n                        85,\n                        82,\n                        88,\n                        82,\n                        90\n                    ],\n                    "name": "Product B",\n                    "itemStyle": {\n                        "color": "#ef4444"\n                    }\n                },\n                {\n                    "value": [\n                        70,\n                        75,\n                        75,\n                        80,\n                        75,\n                        80\n                    ],\n                    "name": "Industry Average",\n                    "itemStyle": {\n                        "color": "#10b981"\n                    }\n                }\n            ]\n        }\n    ]\n}\n\nExample 5 Website Traffic Heat Analysis: {\n    "title": {\n        "text": "User Visit Time Distribution",\n        "subtext": "Scatter Analysis of Visits in Each Time Period of a Week",\n        "left": "center"\n    },\n    "tooltip": {\n        "trigger": "item",\n        "formatter": "Time: {c[0]}<br/>Visits: {c[1]}"\n    },\n    "grid": {\n        "left": "3%",\n        "right": "4%",\n        "bottom": "3%",\n        "containLabel": true\n    },\n    "xAxis": {\n        "type": "value",\n        "name": "Hour",\n        "min": 0,\n        "max": 24\n    },\n    "yAxis": {\n        "type": "value",\n        "name": "Visits"\n    },\n    "series": [\n        {\n            "name": "Visits Distribution",\n            "type": "scatter",\n            "symbolSize": 15,\n            "data": [\n                [\n                    9,\n                    1200\n                ],\n                [\n                    10,\n                    1500\n                ],\n                [\n                    11,\n                    1800\n                ],\n                [\n                    12,\n                    2100\n                ],\n                [\n                    13,\n                    2000\n                ],\n                [\n                    14,\n                    2500\n                ],\n                [\n                    15,\n                    2800\n                ],\n                [\n                    16,\n                    2600\n                ],\n                [\n                    17,\n                    2200\n                ],\n                [\n                    18,\n                    1900\n                ],\n                [\n                    19,\n                    2100\n                ],\n                [\n                    20,\n                    2400\n                ],\n                [\n                    21,\n                    2000\n                ],\n                [\n                    22,\n                    1600\n                ],\n                [\n                    23,\n                    1200\n                ],\n                [\n                    0,\n                    800\n                ]\n            ],\n            "itemStyle": {\n                "color": "#3b82f6",\n                "opacity": 0.6\n            }\n        }\n    ]\n}\n\nRequirements:\n1. Value scales and other information must be clearly displayed.\n2. Only the Echarts chart configuration is returned, with no other redundant content.\n3. When values ​​are negative, a bar chart is used.\n4. The title.label should be consistent with the question summary, using the same language as the question.\n5. Do not use the word "function" in any echarts field!\n6. If the generated chart is meaningless, such as "total number of files," simply return empty.',
	'',
    '[{"input":"input1","name":" 查询出的数据","description":"","is_title":false,"input_type":"text","input_array":[],"is_required":true},{"input":"input2","name":"提问的问题","description":"","is_title":false,"input_type":"text","input_array":[],"is_required":true}]',
    '{"prompt_template":"","doc_forest_ids":null}');
