	('2025-09-28 01:00:00.000', '2025-09-28 01:00:00.000', NULL, @agent_id, '表头行及列名推断机器人', '[1]', '0.5', 'prompt',
	'{{input1}}\n幫我確認表頭行並翻譯為英文。\n回答的列名英文以，分隔，符合資料庫欄位命名規則,用小寫！\n確保回傳的轉換後的列名個數和你確定的原始列名數量嚴格一致，並且數量始終和原始列名數量一致，無法判斷實際意義的直譯成英文即可。\n如果表頭列名為 id，則一律改為 new_id，不要保留為 id。\n同時請以json格式傳回你判斷的列名的行數，範例：\n{\n "columnNames": 轉換後的英文列名數組,\n "columnRealNames": 原始列名數組,\n "headerRow": 表頭行數\n}\n原始列名如果為空，轉換後列名不能為空，應該根據同列的資料推斷列名。\n不要說其他的，只回結論即可！',
	'',
    '[{"input":"input1","name":"数据","description":"用户输入表头行附近的十行数据","is_title":true,"input_type":"text","input_array":[],"is_required":false}]',
    '{"prompt_template":"","doc_forest_ids":null}');
