INSERT INTO `chat_agent_version` (`created_at`, `updated_at`, `deleted_at`, `agent_id`, `description`, `chat_model_ids`, `temperature`, `agent_type`, `prompt_template`, `greeting_message`,`params`, `forest_option`)
VALUES
	('2025-09-28 01:00:00.000', '2025-09-28 01:00:00.000', NULL, @agent_id, '基于数据和 sql 生成对应的 echarts 配置', '[1]', '0.5', 'prompt',
	'查詢出的資料：{{input1}}\n我的問題：{{input2}}\n根據上述數據產生適當的Echarts的圖表配置,\n範例 1 月度銷售長條圖分析：\n{\n    "title": {\n        "text": "月度銷售績效分析",\n        "subtext": "各月份銷售比較",\n        "left": "center"\n    },\n    "tooltip": {\n        "trigger": "axis",\n        "axisPointer": {\n            "type": "shadow"\n        }\n    },\n    "legend": {\n        "data": [\n            "銷量"\n        ],\n        "left": "center",\n        "top": "8%"\n    },\n    "grid": {\n        "left": "3%",\n        "right": "4%",\n        "bottom": "15%",\n        "containLabel": true\n    },\n    "xAxis": {\n        "type": "category",\n        "data": [\n            "一月",\n            "二月",\n            "三月",\n            "四月",\n            "五月",\n            "六月"\n        ]\n    },\n    "yAxis": {\n        "type": "value",\n        "name": "銷量"\n    },\n    "series": [\n        {\n            "name": "銷量",\n            "type": "bar",\n            "data": [\n                120,\n                200,\n                150,\n                80,\n                70,\n                110\n            ],\n            "itemStyle": {\n                "color": "#3b82f6"\n            }\n        }\n    ]\n}\n\n範例2 用戶成長趨勢折線圖：\n{\n    "title": {\n        "text": "使用者成長趨勢分析",\n        "subtext": "近6個月用戶成長情形",\n        "left": "center"\n    },\n    "tooltip": {\n        "trigger": "axis"\n    },\n    "legend": {\n        "data": [\n            "新增使用者"\n        ],\n        "left": "center",\n        "top": "8%"\n    },\n    "grid": {\n        "left": "3%",\n        "right": "4%",\n        "bottom": "15%",\n        "containLabel": true\n    },\n    "xAxis": {\n        "type": "category",\n        "data": [\n            "1月",\n            "2月",\n            "3月",\n            "4月",\n            "5月",\n            "6月"\n        ]\n    },\n    "yAxis": {\n        "type": "value",\n        "name": "使用者數"\n    },\n    "series": [\n        {\n            "name": "新增使用者",\n            "type": "line",\n            "data": [\n                850,\n                932,\n                901,\n                1234,\n                1290,\n                1430\n            ],\n            "smooth": true,\n            "itemStyle": {\n                "color": "#10b981"\n            },\n            "lineStyle": {\n                "width": 3\n            }\n        }\n    ]\n}\n\n範例 3 使用者來源分佈餅圖：\n{\n    "title": {\n        "text": "使用者取得管道分析",\n        "subtext": "各通路用戶佔比",\n        "left": "center"\n    },\n    "backgroundColor": "transparent",\n    "tooltip": {\n        "trigger": "item",\n        "formatter": "{a} <br/>{b}: {c} ({d}%)"\n    },\n    "legend": {\n        "orient": "vertical",\n        "left": "left"\n    },\n    "series": [\n        {\n            "name": "使用者來源",\n            "type": "pie",\n            "radius": "50%",\n            "data": [\n                {\n                    "value": 335,\n                    "name": "搜尋引擎"\n                },\n                {\n                    "value": 310,\n                    "name": "直接存取"\n                },\n                {\n                    "value": 234,\n                    "name": "電子郵件行銷"\n                },\n                {\n                    "value": 135,\n                    "name": "聯盟廣告"\n                },\n                {\n                    "value": 148,\n                    "name": "影片廣告"\n                }\n            ],\n            "emphasis": {\n                "itemStyle": {\n                    "shadowBlur": 10,\n                    "shadowOffsetX": 0,\n                    "shadowColor": "rgba(0, 0, 0, 0.5)"\n                }\n            }\n        }\n    ]\n}\n\n範例 4 產品評分雷達分析：\n{\n    "title": {\n        "text": "產品綜合評分分析",\n        "subtext": "六個維度評估比較",\n        "left": "center"\n    },\n    "tooltip": {\n        "trigger": "item"\n    },\n    "legend": {\n        "data": [\n            "產品A",\n            "產品B",\n            "業界平均"\n        ],\n        "left": "center",\n        "bottom": "5%"\n    },\n    "radar": {\n        "indicator": [\n            {\n                "name": "使用者體驗",\n                "max": 100\n            },\n            {\n                "name": "功能完整度",\n                "max": 100\n            },\n            {\n                "name": "效能表現",\n                "max": 100\n            },\n            {\n                "name": "安全性",\n                "max": 100\n            },\n            {\n                "name": "易用性",\n                "max": 100\n            },\n            {\n                "name": "性愛價比",\n                "max": 100\n            }\n        ],\n        "center": [\n            "50%",\n            "50%"\n        ],\n        "radius": "60%"\n    },\n    "series": [\n        {\n            "name": "產品評分",\n            "type": "radar",\n            "data": [\n                {\n                    "value": [\n                        85,\n                        90,\n                        78,\n                        92,\n                        88,\n                        85\n                    ],\n                    "name": "產品A",\n                    "itemStyle": {\n                        "color": "#3b82f6"\n                    }\n                },\n                {\n                    "value": [\n                        75,\n                        85,\n                        82,\n                        88,\n                        82,\n                        90\n                    ],\n                    "name": "產品B",\n                    "itemStyle": {\n                        "color": "#ef4444"\n                    }\n                },\n                {\n                    "value": [\n                        70,\n                        75,\n                        75,\n                        80,\n                        75,\n                        80\n                    ],\n                    "name": "行業平均",\n                    "itemStyle": {\n                        "color": "#10b981"\n                    }\n                }\n            ]\n        }\n    ]\n}\n\n範例 5 網站流量熱力分析：\n{\n    "title": {\n        "text": "使用者存取時間分佈",\n        "subtext": "一週內各時段訪問量散點分析",\n        "left": "center"\n    },\n    "tooltip": {\n        "trigger": "item",\n        "formatter": "時間: {c[0]}點<br/>訪問量: {c[1]}"\n    },\n    "grid": {\n        "left": "3%",\n        "right": "4%",\n        "bottom": "3%",\n        "containLabel": true\n    },\n    "xAxis": {\n        "type": "value",\n        "name": "小時",\n        "min": 0,\n        "max": 24\n    },\n    "yAxis": {\n        "type": "value",\n        "name": "訪問量"\n    },\n    "series": [\n        {\n            "name": "存取分佈",\n            "type": "scatter",\n            "symbolSize": 15,\n            "data": [\n                [\n                    9,\n                    1200\n                ],\n                [\n                    10,\n                    1500\n                ],\n                [\n                    11,\n                    1800\n                ],\n                [\n                    12,\n                    2100\n                ],\n                [\n                    13,\n                    2000\n                ],\n                [\n                    14,\n                    2500\n                ],\n                [\n                    15,\n                    2800\n                ],\n                [\n                    16,\n                    2600\n                ],\n                [\n                    17,\n                    2200\n                ],\n                [\n                    18,\n                    1900\n                ],\n                [\n                    19,\n                    2100\n                ],\n                [\n                    20,\n                    2400\n                ],\n                [\n                    21,\n                    2000\n                ],\n                [\n                    22,\n                    1600\n                ],\n                [\n                    23,\n                    1200\n                ],\n                [\n                    0,\n                    800\n                ]\n            ],\n            "itemStyle": {\n                "color": "#3b82f6",\n                "opacity": 0.6\n            }\n        }\n    ]\n}\n\n\n要求：\n1、數值比例等內容需明確展示\n2、僅回傳Echarts的圖表配置，無需其他多餘內容。\n3.當數值出現負數的時候，採用長條圖。\n4、title.label根據問題總結，語種和問題一致\n5、echarts 的所有欄位中都不要出現 function ！ ！ ！\n6.如果產生的圖表沒有意義，例如“總共有多少個檔案”回傳空即可',
	'',
